import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# -------------------------------------------------------------------------
# CUDA kernel implementing FP16 1‑D average pooling (same semantics as
# torch.nn.AvgPool1d).  Accumulation is performed in FP32 for numerical
# stability.
# -------------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void avg_pool1d_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    const int batch,
    const int channels,
    const int input_len,
    const int output_len,
    const int kernel_size,
    const int stride,
    const int padding)
{
    // Global linear index for (b, c, out_x)
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = batch * channels * output_len;
    if (idx >= total) return;

    const int out_x = idx % output_len;
    const int c     = (idx / output_len) % channels;
    const int b     = idx / (output_len * channels);

    float sum = 0.0f;
    const int start = out_x * stride - padding;

    #pragma unroll
    for (int k = 0; k < kernel_size; ++k) {
        const int in_x = start + k;
        if (in_x >= 0 && in_x < input_len) {
            sum += static_cast<float>(input[(b * channels + c) * input_len + in_x]);
        }
    }

    const float avg = sum / static_cast<float>(kernel_size);
    output[(b * channels + c) * output_len + out_x] = __float2half(avg);
}

torch::Tensor avg_pool1d_forward(
    torch::Tensor input,
    int64_t kernel_size,
    int64_t stride,
    int64_t padding)
{
    const int batch      = input.size(0);
    const int channels   = input.size(1);
    const int input_len  = input.size(2);
    const int output_len = (input_len + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::empty({batch, channels, output_len}, input.options());

    const int threads = 256;
    const int total   = batch * channels * output_len;
    const int blocks  = (total + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "avg_pool1d_forward", ([&] {
        avg_pool1d_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            batch,
            channels,
            input_len,
            output_len,
            static_cast<int>(kernel_size),
            static_cast<int>(stride),
            static_cast<int>(padding));
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }

    return output;
}
'''

# Compile the kernel as an inline extension
avg_pool1d_mod = load_inline(
    name="avg_pool1d_cuda_ext",
    cpp_sources="",                # no pure C++ sources needed
